after_changes.test_query.py:
import json
from pathlib import Path
import subprocess
import sys
import unittest

from query_adapter import decode_query
from query_cli import handle_query
from query_domain import query_page
from query_store import DocumentStore


class QueryTests(unittest.TestCase):
    def test_default_page(self):
        result = handle_query({})
        self.assertEqual(len(result["items"]), 2)
        self.assertEqual(result["total"], 3)

    def test_explicit_limit(self):
        self.assertEqual(len(handle_query({"limit": "1"})["items"]), 1)

    def test_zero_limit(self):
        for raw in (0, "0"):
            with self.subTest(limit=raw):
                self.assertEqual(decode_query({"limit": raw}), {"limit": 0})
                self.assertEqual(
                    handle_query({"limit": raw}),
                    {"items": [], "total": 3, "limit": 0},
                )

    def test_null_limit_defaults(self):
        result = handle_query({"limit": None})
        self.assertEqual(result, handle_query({}))
        self.assertEqual(result["limit"], 2)

    def test_limit_exceeding_store_size(self):
        for limit in (4, 100):
            with self.subTest(limit=limit):
                result = handle_query({"limit": limit})
                self.assertEqual(len(result["items"]), 3)
                self.assertEqual(result["total"], 3)
                self.assertEqual(result["limit"], limit)

    def test_queries_preserve_store(self):
        store = DocumentStore()
        original = store.read_page(100)
        for limit in (0, 1, 100):
            with self.subTest(limit=limit):
                query_page(store, decode_query({"limit": limit}))
                self.assertEqual(store.read_page(100), original)
                self.assertEqual(store.count(), 3)

    def run_cli(self, query):
        return subprocess.run(
            [sys.executable, str(Path(__file__).with_name("query_cli.py"))],
            input=json.dumps(query),
            text=True,
            capture_output=True,
            check=False,
        )

    def test_cli_zero_limit(self):
        result = self.run_cli({"limit": "0"})
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stderr, "")
        self.assertEqual(
            json.loads(result.stdout), {"items": [], "total": 3, "limit": 0}
        )

    def test_cli_rejects_out_of_range(self):
        for raw in (-1, "-1", 101, "101"):
            with self.subTest(limit=raw):
                result = self.run_cli({"limit": raw})
                self.assertEqual(result.returncode, 2)
                self.assertEqual(result.stdout, "")


if __name__ == "__main__":
    unittest.main()

